8	  <meta name="theme-color" content="#a8b5e8" media="(prefers-color-scheme: light)">
9	  <title>Circle Display</title>
10	  <style>
11	    :root {
12	      --color-white: #ffffff;
13	      --color-gold: #ffd700;
14	      --color-pink: #ff6b9d;
15	      --color-teal: #4ecdc4;
16	      --color-mint: #95e1d3;
17	      --shadow-color: rgba(0, 0, 0, 0.3);
18	      --transition-normal: 0.3s ease;
19	      --transition-slow: 0.6s ease-out;
20	      --pulse-duration: 2.5s;
21	      --color-mode-1-rgb: 255, 107, 157;
22	      --color-mode-2-rgb: 78, 205, 196;
23	      --color-mode-3-rgb: 149, 225, 211;
24	    }
25	
26	    * {
27	      margin: 0;
28	      padding: 0;
29	      box-sizing: border-box;
30	    }
31	    html, body {
32	      width: 100%;
33	      height: 100%;
34	      overflow: hidden;
35	    }
36	    body {
37	      display: flex;
38	      flex-direction: column;
39	      justify-content: center;
40	      align-items: center;
41	      gap: 20px;
42	      background: linear-gradient(135deg, #5f6fd1 0%, #6b3fa0 100%);
43	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
44	      color: var(--color-white);
45	      font-size: 14px;
46	      padding: 20px;
47	      min-height: 100vh;
48	    }
49	    .circle-container {
50	      cursor: pointer;
51	      border: none;
52	      background: none;
53	      padding: 0;
54	      position: relative;
55	      contain: layout style paint;
56	      transition: transform var(--transition-normal);
57	    }
58	    .circle-container:hover {
59	      transform: scale(1.06);
60	    }
61	    .circle-container:focus {
62	      outline: none;
63	    }
64	    .circle-container:focus-visible {
65	      transform: scale(1.08);
66	      outline: 3px solid rgba(255, 255, 255, 0.8);
67	      outline-offset: 10px;
68	      border-radius: 50%;
69	      box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.3);
70	    }
71	    svg {
72	      width: min(400px, 80vw);
73	      height: min(400px, 80vw);
74	      display: block;
75	      animation: fadeIn var(--transition-slow);
76	    }
77	    circle {
78	      fill: var(--color-white);
79	      stroke: rgba(255, 255, 255, 0.25);
80	      stroke-width: 1.5;
81	      animation: pulse var(--pulse-duration) ease-in-out infinite;
82	      filter: drop-shadow(0 20px 40px var(--shadow-color));
83	      transition: fill 0.3s ease, r 0.3s ease, stroke 0.3s ease, filter 0.3s ease;
84	      will-change: r;
85	    }
86	    .circle-container:is(:hover, :focus-visible) circle {
87	      fill: #e8f4f8;
88	      r: 205;
89	      stroke: rgba(255, 255, 255, 0.4);
90	    }
91	    .circle-container.active:not([class*="color-mode-"]) circle {
92	      fill: var(--color-gold);
93	      stroke: rgba(255, 215, 0, 0.3);
94	      animation: pulse-active 0.6s ease-in-out;
95	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
96	      r: 200;
97	    }
