99	    .circle-container.color-mode-1 { --mode-color: var(--color-pink); --mode-rgb: var(--color-mode-1-rgb); }
100	    .circle-container.color-mode-2 { --mode-color: var(--color-teal); --mode-rgb: var(--color-mode-2-rgb); }
101	    .circle-container.color-mode-3 { --mode-color: var(--color-mint); --mode-rgb: var(--color-mode-3-rgb); }
102	
103	    [class*="color-mode-"] circle {
104	      fill: var(--mode-color);
105	      stroke: rgba(var(--mode-rgb), 0.3);
106	      filter: drop-shadow(0 20px 40px rgba(var(--mode-rgb), 0.3));
107	    }
108	    [class*="color-mode-"]:is(:hover, :focus-visible) circle {
109	      stroke: rgba(var(--mode-rgb), 0.5);
110	    }
111	    [class*="color-mode-"].active circle {
112	      animation: pulse-active 0.6s ease-in-out;
113	      filter: drop-shadow(0 20px 40px rgba(var(--mode-rgb), 0.5));
114	    }
115	
116	    .hint {
117	      font-size: 13px;
118	      opacity: 0.95;
119	      transition: opacity var(--transition-normal);
120	      letter-spacing: 0.3px;
121	      max-width: 95%;
122	      line-height: 1.5;
123	      margin-top: 2px;
124	      position: relative;
125	      text-shadow: 0 1px 4px rgba(0, 0, 0, 0.4);
