130	      font-size: 11px;
131	      opacity: 0;
132	      margin-top: 6px;
133	      letter-spacing: 1px;
134	      text-transform: uppercase;
135	      transition: opacity var(--transition-normal), transform 0.3s ease;
136	      height: 18px;
137	      font-weight: 600;
138	      transform: scale(0.95);
139	    }
140	    .mode-indicator.visible {
141	      opacity: 0.95;
142	      transform: scale(1);
143	    }
144	
145	    .controls {
146	      display: flex;
147	      gap: 12px;
148	      margin-top: 6px;
149	      flex-wrap: wrap;
150	      justify-content: center;
151	      width: 100%;
