345	<body>
346	  <main>
347	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - press Space to toggle, double-click to change color" aria-pressed="false">
348	      <svg viewBox="0 0 400 400" aria-hidden="true" role="presentation">
349	        <circle cx="200" cy="200" r="200"/>
350	      </svg>
351	    </button>
352	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
353	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click to activate • Double-click to change color</div>
354	    <div class="controls" role="group" aria-label="Circle controls">
355	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
356	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
357	    </div>
358	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
359	  </main>
360	
361	  <script defer>
362	    const CONFIG = {
363	      storageKey: 'circle-state',
364	      tapDelay: 300,
365	      colorShiftDuration: 500,
366	      colorModes: [
367	        { class: 'default', name: 'Default White' },
368	        { class: 'color-mode-1', name: 'Pink' },
369	        { class: 'color-mode-2', name: 'Teal' },
370	        { class: 'color-mode-3', name: 'Mint' }
371	      ],
372	      isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0,
373	      pulseInterval: 2500
374	    };
375	
376	    const el = {
377	      circle: document.getElementById('decorative-circle'),
378	      hint: document.getElementById('hint-text'),
379	      modeIndicator: document.getElementById('mode-indicator'),
380	      cycleBtn: document.getElementById('cycle-btn'),
381	      resetBtn: document.getElementById('reset-btn')
382	    };
383	
384	    let state = { active: false, colorMode: 0 };
385	    let tapCount = 0;
386	    let tapTimeout = null;
387	    let animatingColorShift = false;
388	
389	    const getColorModeClass = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].class;
390	    const getColorModeName = (mode) => CONFIG.colorModes[mode % CONFIG.colorModes.length].name;
391	
392	    const storage = {
393	      save() {
394	        try {
395	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
396	        } catch {
397	          // Silently fail if localStorage is unavailable or quota exceeded
398	        }
399	      },
400	      load() {
401	        try {
402	          const saved = localStorage.getItem(CONFIG.storageKey);
403	          if (saved) {
404	            const parsed = JSON.parse(saved);
405	            if (parsed && typeof parsed === 'object') {
406	              state = { ...state, ...parsed };
407	            }
408	          }
409	        } catch {
410	          // Silently fail if parsing fails
411	        }
412	      }
413	    };
414	
415	    const updateClasses = () => {
416	      const colorClasses = CONFIG.colorModes.map(m => m.class);
417	      el.circle.classList.remove('active', ...colorClasses);
418	      el.circle.setAttribute('aria-pressed', state.active);
419	      if (state.active) el.circle.classList.add('active');
420	      if (state.colorMode > 0) el.circle.classList.add(getColorModeClass(state.colorMode));
421	    };
422	
423	    const updateUI = () => {
424	      const mainText = state.active ? 'Active!' : 'Click to activate';
425	      let hintParts = [mainText];
426	
427	      if (CONFIG.isTouch) {
428	        hintParts.push(state.active ? 'Tap to change color' : 'Tap twice to change color');
429	      } else {
430	        hintParts.push('Double-click to change color or press C');
431	      }
432	
433	      el.hint.textContent = hintParts.join(' • ');
434	
435	      const showMode = state.active && state.colorMode > 0;
436	      el.modeIndicator.classList.toggle('visible', showMode);
437	      if (showMode) {
438	        const modeName = getColorModeName(state.colorMode);
439	        el.modeIndicator.textContent = `${modeName} — Press R to reset`;
440	      }
441	    };
442	
443	    const applyState = () => {
444	      updateClasses();
445	      updateUI();
446	    };
447	
448	    const toggleActive = () => {
449	      state.active = !state.active;
450	      applyState();
451	      storage.save();
452	    };
453	
454	    const cycleColor = () => {
455	      if (animatingColorShift) return;
456	      animatingColorShift = true;
457	      state.colorMode = (state.colorMode + 1) % CONFIG.colorModes.length;
458	      state.active = true;
459	      el.circle.classList.add('color-shifting');
460	      setTimeout(() => {
461	        el.circle.classList.remove('color-shifting');
462	        animatingColorShift = false;
463	      }, CONFIG.colorShiftDuration);
464	      applyState();
465	      storage.save();
466	    };
467	
468	    const resetState = () => {
469	      state = { active: false, colorMode: 0 };
470	      applyState();
471	      storage.save();
472	    };
473	
474	    const handleDblClick = (e) => {
475	      e.preventDefault();
476	      cycleColor();
477	    };
478	
479	    const handleTouchEnd = () => {
480	      tapCount++;
481	      clearTimeout(tapTimeout);
482	      if (tapCount === 1) {
483	        tapTimeout = setTimeout(() => {
484	          if (tapCount === 1) toggleActive();
485	          tapCount = 0;
486	        }, CONFIG.tapDelay);
487	      } else if (tapCount === 2) {
488	        cycleColor();
489	        tapCount = 0;
490	      }
491	    };
492	
493	    const keyHandlers = {
494	      ' ': toggleActive,
495	      'enter': toggleActive,
496	      'c': cycleColor,
497	      'r': resetState
498	    };
499	
500	    const handleKeyDown = (e) => {
501	      const handler = keyHandlers[e.key.toLowerCase()];
502	      if (handler) {
503	        e.preventDefault();
504	        handler();
505	      }
506	    };
507	
508	    const initListeners = () => {
509	      el.circle.addEventListener('click', toggleActive);
510	      el.circle.addEventListener('dblclick', handleDblClick);
511	      el.circle.addEventListener('touchend', handleTouchEnd);
512	      el.circle.addEventListener('blur', () => {
513	        tapCount = 0;
514	        clearTimeout(tapTimeout);
515	      });
516	      document.addEventListener('keydown', handleKeyDown);
517	      el.cycleBtn.addEventListener('click', cycleColor);
518	      el.resetBtn.addEventListener('click', resetState);
519	    };
520	
521	    const initApp = () => {
522	      storage.load();
523	      applyState();
524	      initListeners();
525	      requestAnimationFrame(() => el.circle.focus());
526	    };
527	
528	    if (document.readyState === 'loading') {
529	      document.addEventListener('DOMContentLoaded', initApp);
530	    } else {
531	      initApp();
532	    }
533	  </script>
534	</body>
535	</html>
