const updateUI = () => {
  const mainText = state.active ? 'Active!' : 'Click to activate';
  let hintParts = [mainText];

  if (CONFIG.isTouch) {
    hintParts.push(state.active ? 'Tap to change color' : 'Tap twice to change color');
  } else {
    hintParts.push('Double-click to change color or press C');
  }

  el.hint.textContent = hintParts.join(' • ');

  const showMode = state.active && state.colorMode > 0;
  el.modeIndicator.classList.toggle('visible', showMode);
  if (showMode) {
    const modeName = getColorModeName(state.colorMode);
    el.modeIndicator.textContent = `${modeName} — Press R to reset`;
  }
};

